package com.writhlang.time

import java.time.LocalDate

/**
 * Cashflow date generation.
 *
 * Dates are generated by adding a whole number of **months** to the anchor date,
 * so a schedule is "the same day-of-month every period". Generating each date
 * from the anchor (rather than chaining from the previous date) keeps a 31st-of-
 * the-month schedule from drifting, and month-end roll-over is Java's calendar
 * semantics (e.g. 2024-01-31 + 1M = 2024-02-29).
 *
 * Each generated date is rolled onto a business day by the configured
 * [[BusinessDayConvention]]. The accrual of a period is always the year fraction
 * between the *adjusted* previous date and the *adjusted* next date, so period
 * accruals are exact under the day-count convention.
 */
object Schedule {

  /** Months in one period of a `freq`-per-year schedule, or a clear error. */
  def monthsPerPeriod(freq: Int): Either[String, Int] =
    if (freq <= 0) Left(s"frequency must be a positive integer, got $freq")
    else if (12 % freq != 0) Left(s"frequency must divide 12 (1, 2, 3, 4, 6 or 12), got $freq")
    else Right(12 / freq)

  /**
   * `periods` dates after `start`, one every `monthsPerPeriod` months, each
   * rolled onto a business day. The dates are strictly increasing for positive
   * `monthsPerPeriod`.
   */
  def dates(
    start: LocalDate,
    periods: Int,
    monthsPerPeriod: Int,
    conventions: TimeConventions
  ): Vector[LocalDate] = {
    require(monthsPerPeriod > 0, s"months per period must be positive, got $monthsPerPeriod")
    require(periods >= 0, s"period count must be non-negative, got $periods")
    (1 to periods).map { period =>
      conventions.adjust(start.plusMonths(period.toLong * monthsPerPeriod))
    }.toVector
  }

  /** The unadjusted end date of a term quoted in whole months. */
  def endDate(start: LocalDate, months: Long): LocalDate = start.plusMonths(months)

  /**
   * The unadjusted end date of a term quoted in (possibly fractional) years,
   * rounded to whole months. Used for terms expressed as a year count in the
   * DSL (`expiry 1.5`, `maturity 2.25`) where no explicit date exists.
   */
  def endDateFromYears(start: LocalDate, years: Double): LocalDate =
    start.plusMonths(math.round(years * 12.0))
}
